<?php require '_auth.php';$id=(int)($_GET['id']??0);$p=['name'=>'','category'=>'Fashion','price'=>'','stock'=>10,'image'=>'assets/images/fashion.svg','description'=>'','status'=>'active'];if($id){$st=$pdo->prepare("SELECT * FROM products WHERE id=?");$st->execute([$id]);$p=$st->fetch()?:$p;}if($_SERVER['REQUEST_METHOD']==='POST'){$data=[$_POST['name'],$_POST['category'],$_POST['price'],$_POST['stock'],$_POST['image'],$_POST['description'],$_POST['status']];if($id){$data[]=$id;$pdo->prepare("UPDATE products SET name=?,category=?,price=?,stock=?,image=?,description=?,status=? WHERE id=?")->execute($data);}else{$pdo->prepare("INSERT INTO products(name,category,price,stock,image,description,status) VALUES(?,?,?,?,?,?,?)")->execute($data);}header('Location:products.php');exit;}$adminTitle=$id?'Edit Product':'Add Product';include '_header.php';?><form class="panel" method="post"><div class="form-grid"><div class="field"><label>Product name</label><input name="name" value="<?=e($p['name'])?>" required></div><div class="field"><label>Category</label><select name="category"><?php foreach(['Fashion','Technology','Home','Beauty'] as $c):?><option <?=$p['category']==$c?'selected':''?>><?=$c?></option><?php endforeach;?></select></div><div class="field"><label>Price (LKR)</label><input type="number" step="0.01" name="price" value="<?=e($p['price'])?>" required></div><div class="field"><label>Stock</label><input type="number" name="stock" value="<?=e($p['stock'])?>" required></div><div class="field"><label>Image path</label><input name="image" value="<?=e($p['image'])?>" required></div><div class="field"><label>Status</label><select name="status"><option <?=$p['status']=='active'?'selected':''?>>active</option><option <?=$p['status']=='inactive'?'selected':''?>>inactive</option></select></div></div><div class="field"><label>Description</label><textarea name="description"><?=e($p['description'])?></textarea></div><button class="btn">Save product</button> <a class="btn gray" href="products.php">Cancel</a></form><?php include '_footer.php';?>
